#!/bin/bash
# Every policy is left in report-only, so nothing is actually enforced.
set -e
python3 - <<'PY'
import json, os
P = "/home/learner/ca/policies"
os.makedirs(P, exist_ok=True)
for f in os.listdir(P):
    os.remove(os.path.join(P, f))
pols = {'10-everyone-mfa.json': {'displayName': 'Everyone: multifactor authentication', 'state': 'enabledForReportingButNotEnforced', 'conditions': {'users': {'includeUsers': ['All'], 'excludeGroups': ['emergency-access']}, 'applications': {'includeApplications': ['All']}}, 'grantControls': {'operator': 'AND', 'builtInControls': ['mfa']}}, '20-admins-phishing-resistant.json': {'displayName': 'Admins: phishing-resistant', 'state': 'enabledForReportingButNotEnforced', 'conditions': {'users': {'includeGroups': ['partner-admins'], 'includeRoles': ['Global Administrator'], 'excludeGroups': ['emergency-access']}, 'applications': {'includeApplications': ['All']}}, 'grantControls': {'operator': 'OR', 'authenticationStrength': {'displayName': 'Phishing-resistant MFA'}}}, '30-contractors-warehouse-only.json': {'displayName': 'Contractors: the partner portal only from the warehouse', 'state': 'enabledForReportingButNotEnforced', 'conditions': {'users': {'includeGroups': ['contractors'], 'excludeGroups': ['emergency-access']}, 'applications': {'includeApplications': ['partner-portal']}, 'locations': {'includeLocations': ['All'], 'excludeLocations': ['warehouse']}}, 'grantControls': {'operator': 'OR', 'builtInControls': ['block']}}, '40-risk-medium.json': {'displayName': 'Medium sign-in risk: phishing-resistant', 'state': 'enabledForReportingButNotEnforced', 'conditions': {'users': {'includeUsers': ['All'], 'excludeGroups': ['emergency-access']}, 'applications': {'includeApplications': ['All']}, 'signInRiskLevels': ['medium']}, 'grantControls': {'operator': 'OR', 'authenticationStrength': {'displayName': 'Phishing-resistant MFA'}}}, '41-risk-high-block.json': {'displayName': 'High sign-in risk: block', 'state': 'enabledForReportingButNotEnforced', 'conditions': {'users': {'includeUsers': ['All'], 'excludeGroups': ['emergency-access']}, 'applications': {'includeApplications': ['All']}, 'signInRiskLevels': ['high']}, 'grantControls': {'operator': 'OR', 'builtInControls': ['block']}}, '50-legacy-block.json': {'displayName': 'Legacy authentication: block', 'state': 'enabledForReportingButNotEnforced', 'conditions': {'users': {'includeUsers': ['All'], 'excludeGroups': ['emergency-access']}, 'applications': {'includeApplications': ['All']}, 'clientAppTypes': ['exchangeActiveSync', 'other']}, 'grantControls': {'operator': 'OR', 'builtInControls': ['block']}}, '60-portal-compliant-report-only.json': {'displayName': 'Partner portal needs a compliant device (report-only)', 'state': 'enabledForReportingButNotEnforced', 'conditions': {'users': {'includeUsers': ['All']}, 'applications': {'includeApplications': ['partner-portal']}}, 'grantControls': {'operator': 'AND', 'builtInControls': ['compliantDevice']}}}
for name, d in pols.items():
    json.dump(d, open(os.path.join(P, name), 'w'), indent=2)
PY
